SELECT S.*, C.KOR AS STORE_TYPE FROM STORE S LEFT JOIN CODE C ON S.S_CATEGORY = C.VALUE AND C.TYPE = 'S_CATEGORY' -- 업체 정책 테이블 JOIN LEFT JOIN STORE_POLICY SP ON S.STORE_NO = SP.STORE_NO WHERE S.LAT BETWEEN #{swLat} AND #{neLat} AND S.LNG BETWEEN #{swLng} AND #{neLng}
AND C.KOR = #{storeType}
AND ( -- 1. 비회원사(ext)는 항상 노출 S.S_STATUS = 'ext'
OR
-- 2. 회원사(gen)는 슬롯 및 업체별 Cutoff 정책 확인 (S.S_STATUS = 'gen' AND EXISTS ( SELECT 1 FROM RSV_SLOT RS WHERE RS.STORE_NO = S.STORE_NO AND RS.SLOT_DATE BETWEEN #{startDate} AND #{endDate} AND RS.SLOT_TIME BETWEEN #{startTime} AND #{endTime} AND RS.IS_AVAILABLE = 'Y'
-- [핵심] SP.CUTOFF 값을 가져와 현재 시간과 비교 (설정값 없으면 기본값 0 적용) -- 슬롯 일시가 (현재 시간 + 업체별 마감 시간)보다 미래여야 함 AND TIMESTAMP(RS.SLOT_DATE, RS.SLOT_TIME) > DATE_ADD(NOW(), INTERVAL COALESCE(SP.CUTOFF, 0) HOUR) )) )

SELECT R.USER_ID, NICKNAME, RATING, R_CONTENTS, DATE_FORMAT(R.CDATE, '%Y-%m-%d %H:%i') AS cdate, RSV_NO FROM REVIEW R JOIN USERS U ON R.USER_ID = U.USER_ID WHERE STORE_NO = #{storeNo}
AND RSV_NO = #{rsvNo}
ORDER BY R.CDATE DESC LIMIT 2

mapper.update:
UPDATE RSV_SLOT S
JOIN STORE_POLICY SP ON S.STORE_NO = SP.STORE_NO
SET 
    S.CUR_COUNT = S.CUR_COUNT + 1,
    /* 수용 인원 도달 시 N으로 변경, 아니면 Y 유지 */
    S.IS_AVAILABLE = CASE 
                        WHEN S.CUR_COUNT + 1 >= S.CAPACITY THEN 'N'
                        ELSE 'Y'
                     END
WHERE S.SLOT_NO = #{slotNo}
  /* 정책상 마감 시간(Cutoff) 이내인지 확인 */

  AND TIMESTAMP(S.SLOT_DATE, S.SLOT_TIME) > DATE_ADD(NOW(), INTERVAL COALESCE(SP.CUTOFF, 0) HOUR)

  /* 결제 팀원이 업데이트한 상태(CNF) 확인 */
  AND EXISTS (
      SELECT 1 
      FROM RESERVATION R 
      WHERE R.RSV_NO = #{rsvNo} 
        AND R.RSV_STATUS = 'CNF'
  )

UPDATE RESERVATION
SET RSV_STATUS = 'CAN'
WHERE RSV_NO = #{rsvNo}

UPDATE RESERVATION 
SET RSV_STATUS = 'FIN'
WHERE RSV_NO = #{rsvNo}
